            file << "                g_logFile << \"[ALLOC-\" << (_v0 == 0 ? \"FAIL\" : \"WILD\") << \"] FUN_002044f8 v0=0x\" << std::hex << _v0\n";
            file << "                          << \" size=0x\" << _size << \" ra=0x\" << _ra << std::dec << std::endl;\n";
            file << "                // [BIGHEAP-FLAG] FUN_002049f8 (the size>=0x1000 path this call took)\n";
            file << "                // returns NULL immediately when allocator+0x30 == 0. PCSX2 ground\n";
            file << "                // truth: ctx @0x31afb8, flag @0x31afe8 == 1, heap base 0xa83fe0.\n";
            file << "                // Dump the allocator context so we can see WHICH field diverges.\n";
