            file << "        static int _n = 0; if (_n < 12) { _n++;\n";
            file << "            g_logFile << \"[BIGHEAP-INIT] FUN_00204740 a0=0x\" << std::hex << _a0\n";
            file << "                      << \" ra=0x\" << _ra << \" flag@0x31afe8: 0x\" << _pre\n";
            file << "                      << \" -> 0x\" << _post << std::dec << std::endl;\n";
