            file << "        uint32_t _obj = ctx.cpuRegs.GPR.r[4].UL[0];\n";
            file << "        uint32_t _ra  = ctx.cpuRegs.GPR.r[31].UL[0];\n";
            file << "        uint32_t _phys = _obj & 0x1FFFFFFFu;\n";
            file << "        if (_phys < 0x100000u) {\n";
            file << "            static int _n = 0; if (_n < 24) { _n++;\n";
            file << "                g_logFile << \"[BADOBJ-CTOR] FUN_001ffdc0 obj=0x\" << std::hex << _obj\n";
            file << "                          << \" caller_ra=0x\" << _ra << std::dec << std::endl;\n";
            file << "            }\n";
            file << "        }\n";
            file << "        FUN_001ffdc0(ctx, addr);\n";
            file << "    };\n";
            uint32_t end_address = func.base_address + func.size;
