            // so we can see WHO has the uninitialized/coincident position. Unfiltered tag.
            file << "    recompiled_functions[0x194040] = [](CpuContext& ctx, uint32_t addr) {\n";
            file << "        uint32_t _obj = ctx.cpuRegs.GPR.r[4].UL[0];\n";
