            file << "        uint32_t _pp  = _p94 ? memory::read<uint32_t>(_p94) : 0u;\n";
            file << "        uint32_t _cam = _pp ? memory::read<uint32_t>(_pp + 0x8u) : 0u;\n";
            file << "        auto _rdf = [](uint32_t a){ uint32_t _w = memory::read<uint32_t>(a); return *reinterpret_cast<float*>(&_w); };\n";
            file << "        float _cx=0,_cy=0,_cz=0,_nx=0,_ny=0,_nz=0;\n";
            file << "        if (_cam) {\n";
            file << "            _cx=_rdf(_cam+0x40u); _cy=_rdf(_cam+0x44u); _cz=_rdf(_cam+0x48u);\n";
            file << "            _nx=_rdf(_cam+0x10u); _ny=_rdf(_cam+0x14u); _nz=_rdf(_cam+0x18u);\n";
