            file << "        float _ox=_rdf(_obj+0x30u), _oy=_rdf(_obj+0x34u), _oz=_rdf(_obj+0x38u);\n";
            file << "        uint64_t _flags = memory::read<uint64_t>(_obj + 0xb8u);\n";
            file << "        float _dx=_tx-_cx, _dy=_ty-_cy, _dz=_tz-_cz;\n";
