            file << "                          << \" quatpost=\" << _q0 << \" \" << _q1 << \" \" << _q2 << \" \" << _q3\n";
            file << "                          << std::dec << std::endl;\n";
            file << "            }\n";
            file << "        }\n";
            file << "    };\n";
