            file << "    recompiled_functions[0x294b18] = [](CpuContext& ctx, uint32_t addr) {\n";
            file << "        extern uint32_t g_pose_wb_count;\n";
            file << "        extern std::atomic<uint32_t> g_vsync_frame;\n";
            file << "        g_pose_wb_count++;\n";
            file << "        if (addr == 0x294b18) {\n";  // count only fresh entries, not block re-entry
            file << "            static uint32_t _f = 0;\n";
            file << "            static std::map<uint32_t, uint32_t> _rows;   // stream ctx -> rows this frame\n";
            file << "            static int _lines = 0;\n";
            file << "            uint32_t _cf = g_vsync_frame.load(std::memory_order_relaxed);\n";
            file << "            uint32_t _ctx3 = ctx.cpuRegs.GPR.r[7].UL[0];\n";
            file << "            if (_cf != _f) {\n";
