        // ----------------------------------------------------------------
        // VU0 (COP2) Broadcast & Accumulator Arithmetic
        // ----------------------------------------------------------------


        case rabbitizer::InstrId::UniqueId::r5900_vsubx:
            // vsubx.xyzw fd, fs, ft  ->  fd[mask] = fs - {ft.x, ft.x, ft.x, ft.x}
            file << "    // vsubx - Vector Subtract (Broadcast X)\n";
