                std::string fd = get_vr_name(static_cast<uint8_t>(instr.GetO32_fd()));
                std::string fs = get_vr_name(static_cast<uint8_t>(instr.GetO32_fs()));
                std::string ft = get_vr_name(static_cast<uint8_t>(instr.GetO32_ft()));
