            file << "    {\n";
            file << "        auto rs = " << get_gpr_name(static_cast<uint8_t>(instr.GetO32_rs())) << ";\n";
            file << "        auto rt = " << get_gpr_name(static_cast<uint8_t>(instr.GetO32_rt())) << ";\n";
            file << "        auto& rd = " << get_gpr_name(static_cast<uint8_t>(instr.GetO32_rd())) << ";\n";
