            uint8_t rt = static_cast<uint8_t>(instr.GetO32_rt());
            uint8_t rd = static_cast<uint8_t>(instr.GetO32_rd());
            
            bool interlocked = (instr.getUniqueId() == rabbitizer::InstrId::UniqueId::r5900_cfc2_i);
            file << "    // cfc2" << (interlocked ? ".i" : ".ni") 
                << " - Copy from VU0 control register " << std::dec << (int)rd << " to GPR[" << (int)rt << "]\n";
            
            if (rt == 0) {
                file << "    // rt=0, write ignored\n";
                break;
            }
            
            file << "    {\n";
            file << "        int32_t value = 0;\n";
            file << "        switch (" << std::dec << (int)rd << ") {\n";
            file << "            case 0: value = 0; break;  // VI0 always 0\n";
            file << "            case 1: case 2: case 3: case 4: case 5: case 6: case 7:\n";
            file << "            case 8: case 9: case 10: case 11: case 12: case 13: case 14: case 15:\n";
            file << "                // VI registers are 16-bit unsigned. The upper 16 bits of\n";
            file << "                // the 32-bit COP2 control register are always 0 (per VU\n";
            file << "                // manual section 5.1.2). Zero-extend, never sign-extend.\n";
            file << "                value = static_cast<int32_t>(static_cast<uint32_t>(\n";
            file << "                            static_cast<uint16_t>(ctx.vuRegs.VI[" << std::dec << (int)rd << "])));\n";
            file << "                break;\n";
            file << "            case 16: value = static_cast<int32_t>(ctx.vuRegs.status_flag); break;\n";
            file << "            case 17: value = static_cast<int32_t>(ctx.vuRegs.mac_flag); break;\n";
            file << "            case 18: value = static_cast<int32_t>(ctx.vuRegs.clip_flag); break;\n";
            file << "            case 20: value = static_cast<int32_t>(ctx.vuRegs.R); break;\n";
            file << "            case 21: value = static_cast<int32_t>(ctx.vuRegs.I); break;\n";
            file << "            case 22: value = static_cast<int32_t>(*reinterpret_cast<uint32_t*>(&ctx.vuRegs.Q)); break;\n";
            file << "            case 26: value = static_cast<int32_t>(ctx.vuRegs.TPC); break;\n";
